      const terminal = terminalEffectFromRecord(claim.record);
      if (Option.isSome(terminal)) {
        return yield* resultForCurrentEffect(dependencies.protections, terminal.value, true);
      }
      if (claim.outcome === 'EXACT_REPLAY') {
        return claim.record.currentState === 'INDETERMINATE'
          ? yield* resolveAuthority(claim.record, current, history, request, true)
          : indeterminateResult(payload.effectId, true);
      }
      const effective = confirmationEffectiveAt(current, history, claim.record.requestedAt);
      const readiness = yield* evaluateReservationConfirmationCommitment(effective, {
        evaluatedAt: claim.record.requestedAt,
      }).pipe(Effect.mapError((cause) => Object.assign(rejected(payload.effectId, 'INVALID_PROTECTION'), { cause })));
